    void status(String text,boolean editing)
    {
        SwingUtilities.invokeLater(() -> { status.setText("<html>"+escape(text)+"</html>"); arrange.setSelected(editing); });
    }
    void syncStatus(String text,boolean active,String hostName)
    {
        String key=active+":"+hostName;
        SwingUtilities.invokeLater(() -> {
            syncStatus.setText("<html>"+escape(text)+"</html>");
            // Don't overwrite a host name or checkbox the user is currently editing.
            if(!key.equals(lastSync)) { syncEnabled.setSelected(active); host.setText(hostName); lastSync=key; }
        });
    }
    private static String escape(String s) { return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\n","<br>"); }
}

package com.docsultan.groupstorage;

import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.*;

/** Immutable snapshot shared with the AWT mouse listener and overlay. */
final class StorageView
{
    final Rectangle bounds;
    final int scrollY, visibleSlots;
    final GridGeometry grid;
    final List<Integer> items;
    final Map<Integer, BufferedImage> missing;
    final long epoch;
    final boolean arranging;

    StorageView(Rectangle bounds,int scrollY,int visibleSlots,GridGeometry grid,List<Integer> items,
                Map<Integer,BufferedImage> missing,long epoch,boolean arranging)
    {
        this.bounds=new Rectangle(bounds); this.scrollY=scrollY; this.visibleSlots=visibleSlots;
        this.grid=grid; this.items=items; this.missing=Collections.unmodifiableMap(new HashMap<>(missing));
        this.epoch=epoch; this.arranging=arranging;
    }
    int slotAt(int x,int y)
    {
        if(!bounds.contains(x,y)) return -1;
        int slot=grid.slotAt(x-bounds.x,y-bounds.y+scrollY);
        return slot>=0 && slot<visibleSlots?slot:-1;
    }
    int itemAt(int slot) { return slot>=0 && slot<items.size()?items.get(slot):-1; }
    Rectangle cell(int slot)
    {
        Rectangle r=grid.cell(slot); r.translate(bounds.x,bounds.y-scrollY); return r;
    }
}

package com.docsultan.groupstorage;

import net.runelite.api.widgets.Widget;
import java.awt.Rectangle;

/** Only geometry/visibility/drag timing change. Native IDs, indices, actions and listeners stay intact. */
final class WidgetPlacement
{
    final Widget widget;
    final int x,y,dragTime;
    final boolean hidden;
    WidgetPlacement(Widget widget)
    {
        this.widget=widget;
        x=widget.getOriginalX(); y=widget.getOriginalY();
        hidden=widget.isSelfHidden(); dragTime=widget.getDragDeadTime();
    }
    void place(Rectangle cell)
    {
        widget.setOriginalX(cell.x); widget.setOriginalY(cell.y);
        widget.setHidden(false);
        // Layout dragging is handled locally in Arrange mode. Never send native storage reorder drags.
        widget.setDragDeadTime(Integer.MAX_VALUE);
        widget.revalidate();
    }
    void restore()
    {
        widget.setOriginalX(x); widget.setOriginalY(y);
        widget.setHidden(hidden); widget.setDragDeadTime(dragTime); widget.revalidate();
    }
}

