package com.docsultan.groupstorage;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LayoutSyncTest
{
    long now=1000;
    final List<Node> nodes=new ArrayList<>();
    final Deque<GroupStorageLayoutSyncMessage> network=new ArrayDeque<>();
    final class Node
    {
        final long id;
        final LayoutSync sync;
        StorageLayout saved;
        final List<String> notices=new ArrayList<>();
        int commits;
        Node(long id,boolean host,Integer... initial)
        {
            this.id=id; saved=initial==null?null:new StorageLayout(Arrays.asList(initial)); nodes.add(this);
            sync=new LayoutSync(host,id,1,"group",saved,m -> { m.setMemberId(id); network.add(m); },
                layout -> { saved=layout; commits++; },notices::add,() -> now);
        }
    }
    void flush()
    {
        int count=0;
        while(!network.isEmpty())
        {
            assertTrue("No rebroadcast loop",++count<100);
            GroupStorageLayoutSyncMessage m=network.remove();
            for(Node node:new ArrayList<>(nodes)) node.sync.receive(m);
        }
    }
    void connect(Node... followers) { for(Node n:followers) n.sync.tick(); flush(); }
    void equal(Node... all) { for(Node n:all) assertEquals(all[0].saved.encode(),n.saved.encode()); }

    @Test public void missingHostLayoutIsReportedWithoutReplacingFollowersAndCaptureRecovers()
    {
        Node a=new Node(1,true,(Integer[])null), b=new Node(2,false,999), c=new Node(3,false,333);
        connect(b,c);
        assertFalse(a.sync.hasLayout());
        for(Node n:Arrays.asList(b,c))
        {
            assertTrue(n.sync.hostNeedsLayout()); assertFalse(n.sync.ready());
            assertEquals(0,n.commits); assertFalse(n.sync.move(0,1,n.saved.itemAt(0)));
        }
        assertEquals(999,b.saved.itemAt(0)); assertEquals(333,c.saved.itemAt(0));
        a.sync.replace(new StorageLayout(Arrays.asList(100,200))); flush();
        now+=LayoutSync.POLL_MS; connect(b,c);
        equal(a,b,c); assertTrue(b.sync.ready()); assertFalse(b.sync.hostNeedsLayout());
        assertTrue(c.sync.move(0,2,100)); flush(); equal(a,b,c);
    }
    @Test public void missingLayoutReplyMustBeFreshAndFromHostAndExpires()
    {
        Node a=new Node(1,true,(Integer[])null), b=new Node(2,false,999);
        b.sync.tick(); a.sync.receive(network.remove()); GroupStorageLayoutSyncMessage reply=network.remove();
        reply.setMemberId(3); b.sync.receive(reply); assertFalse(b.sync.hostNeedsLayout());
        reply.setMemberId(1); now+=LayoutSync.POLL_MS; b.sync.tick();
        b.sync.receive(reply); assertFalse(b.sync.hostNeedsLayout());
        flush(); assertTrue(b.sync.hostNeedsLayout());
        now+=LayoutSync.TIMEOUT_MS; assertFalse(b.sync.hostNeedsLayout());
        assertEquals(999,b.saved.itemAt(0)); assertEquals(0,b.commits);
    }
    @Test public void delayedMissingLayoutReplyCannotPauseNewerSnapshot()
    {
        Node a=new Node(1,true,(Integer[])null), b=new Node(2,false,999);
        b.sync.tick(); GroupStorageLayoutSyncMessage request=network.remove();
        a.sync.receive(request); GroupStorageLayoutSyncMessage delayed=network.remove();
        a.sync.replace(new StorageLayout(Arrays.asList(100,200))); flush();
        a.sync.receive(request); flush(); assertTrue(b.sync.ready());
        b.sync.receive(delayed); assertTrue(b.sync.ready()); assertFalse(b.sync.hostNeedsLayout()); equal(a,b);
    }
    @Test public void restartedHostWithoutLayoutPausesFollowerAndKeepsLastGoodCopy()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false,999); connect(b);
        nodes.remove(a); Node restarted=new Node(1,true,(Integer[])null);
        now+=LayoutSync.POLL_MS; connect(b);
        assertTrue(b.sync.hostNeedsLayout()); assertFalse(b.sync.ready()); assertEquals(100,b.saved.itemAt(0));
        restarted.sync.replace(new StorageLayout(Arrays.asList(300,400))); flush();
        now+=LayoutSync.POLL_MS; connect(b); equal(restarted,b); assertTrue(b.sync.ready());
    }

    @Test public void threeClientsJoinAndAnyMemberCanDrag()
    {
        Node a=new Node(1,true,100,200,300), b=new Node(2,false,999), c=new Node(3,false,333);
        connect(b,c); equal(a,b,c);
        assertTrue(b.sync.move(0,10,100)); assertEquals(100,b.saved.itemAt(0));
        flush(); equal(a,b,c); assertEquals(100,c.saved.itemAt(10));
        assertTrue(c.sync.move(1,2,200)); flush(); equal(a,b,c);
        assertTrue(a.sync.move(10,0,100)); flush(); equal(a,b,c);
        assertFalse(b.sync.pending()); assertFalse(c.sync.pending());
    }
    @Test public void simultaneousDragsRejectStaleRequestWithoutOverwriting()
    {
        Node a=new Node(1,true,100,200,300), b=new Node(2,false), c=new Node(3,false);
        connect(b,c);
        assertTrue(b.sync.move(0,5,100)); assertTrue(c.sync.move(1,6,200)); flush();
        equal(a,b,c); assertEquals(100,a.saved.itemAt(5)); assertEquals(200,a.saved.itemAt(1));
        assertEquals(1,c.notices.size()); assertFalse(c.sync.pending());
        assertTrue(c.sync.move(1,6,200)); flush(); equal(a,b,c);
    }
    @Test public void duplicateMoveCannotSwapBack()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        b.sync.move(0,1,100); GroupStorageLayoutSyncMessage move=network.peek(); network.add(move); flush();
        equal(a,b); assertEquals(100,a.saved.itemAt(1)); assertEquals(1,a.sync.revision());
    }
    @Test public void oldBroadcastCannotRollBackNewRevision()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        a.sync.move(0,1,100); GroupStorageLayoutSyncMessage old=network.peek(); flush();
        a.sync.move(1,3,100); flush(); b.sync.receive(old);
        equal(a,b); assertEquals(100,b.saved.itemAt(3));
    }
    @Test public void droppedBroadcastCatchesUpOnPollWithoutRepeatedWrites()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        a.sync.move(0,1,100); network.clear();
        now+=5000; b.sync.tick(); flush(); equal(a,b);
        int commits=b.commits; now+=5000; b.sync.tick(); flush(); assertEquals(commits,b.commits);
    }
    @Test public void hostOfflinePausesEditsButKeepsLayout()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        now+=15000; assertFalse(b.sync.ready()); assertFalse(b.sync.move(0,1,100));
        assertEquals(100,b.saved.itemAt(0));
        b.sync.tick(); flush(); assertTrue(b.sync.ready()); equal(a,b);
    }
    @Test public void restartedHostNeedsFreshHandshakeAndOldSessionIsRejected()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        a.sync.move(0,1,100); GroupStorageLayoutSyncMessage old=network.peek(); flush();
        nodes.remove(a); Node restarted=new Node(1,true,300,400);
        restarted.sync.replace(restarted.saved); flush(); assertEquals(100,b.saved.itemAt(1));
        now+=5000; b.sync.tick(); flush(); equal(restarted,b);
        b.sync.receive(old); equal(restarted,b);
    }
    @Test public void staleChallengeResponseCannotInitializeNewFollowerSession()
    {
        Node a=new Node(1,true,100), b=new Node(2,false,999);
        b.sync.tick(); a.sync.receive(network.remove()); GroupStorageLayoutSyncMessage old=network.remove();
        now+=5000; b.sync.tick(); b.sync.receive(old); assertFalse(b.sync.ready());
        flush(); equal(a,b);
    }
    @Test public void missingAcknowledgementExpiresAndRefreshes()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        b.sync.move(0,1,100); network.clear(); assertFalse(b.sync.move(0,2,100));
        now+=15000; b.sync.tick(); flush(); assertFalse(b.sync.pending()); equal(a,b);
        assertEquals(1,b.notices.size()); assertTrue(b.sync.move(0,1,100)); flush(); equal(a,b);
    }
    @Test public void newcomerObservationsAppendOnceWithoutFillingGaps()
    {
        Node a=new Node(1,true,100,-1,200), b=new Node(2,false), c=new Node(3,false);
        b.sync.observe(Arrays.asList(100,300)); c.sync.observe(Arrays.asList(300,400));
        connect(b,c); equal(a,b,c);
        assertEquals(Arrays.asList(100,-1,200,300,400),a.saved.items());
        long revision=a.sync.revision(); now+=5000; connect(b,c); assertEquals(revision,a.sync.revision());
    }
    @Test public void malformedAndWrongHostPacketsAreIgnored()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        a.sync.move(0,1,100); GroupStorageLayoutSyncMessage m=network.remove();
        m.setMemberId(3); b.sync.receive(m); assertEquals(100,b.saved.itemAt(0));
        m.setMemberId(1); m.protocol=2; b.sync.receive(m); assertEquals(100,b.saved.itemAt(0));
        m.protocol=1; m.group="other"; b.sync.receive(m); assertEquals(100,b.saved.itemAt(0));
        m.group="group"; m.layout="GSL1:100,100"; b.sync.receive(m); assertEquals(100,b.saved.itemAt(0));
        m.layout="GSL1:200,100"; m.revision=-1; b.sync.receive(m); assertEquals(100,b.saved.itemAt(0));
    }
    @Test public void invalidMoveCannotExpandOrCorruptLayout()
    {
        Node a=new Node(1,true,100,200), b=new Node(2,false); connect(b);
        b.sync.move(0,1,100); GroupStorageLayoutSyncMessage m=network.remove();
        m.target=2048; a.sync.receive(m); flush(); equal(a,b); assertEquals(100,a.saved.itemAt(0));
        assertFalse(a.sync.move(-1,1,100)); assertFalse(a.sync.move(0,1,200));
    }
    @Test public void fullLayoutObservationsAreAtomic()
    {
        Integer[] ids=new Integer[2048]; for(int i=0;i<ids.length;i++) ids[i]=i+1;
        Node a=new Node(1,true,ids), b=new Node(2,false); b.sync.observe(Arrays.asList(9000,9001));
        connect(b); equal(a,b); assertEquals(2048,a.saved.size()); assertEquals(0,a.sync.revision());
    }
    @Test public void followersCannotReplaceHostLayout()
    {
        Node b=new Node(2,false,100);
        try { b.sync.replace(new StorageLayout()); fail(); } catch(IllegalStateException expected) { }
        assertEquals(100,b.saved.itemAt(0));
    }
}

package com.docsultan.groupstorage;

import java.util.*;
import org.junit.*;
import org.mockito.ArgumentCaptor;
import net.runelite.api.*;
import net.runelite.api.clan.*;
import net.runelite.client.party.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class PartyLayoutSyncTest
{
    Client client=mock(Client.class);
    GroupStoragePlugin plugin=mock(GroupStoragePlugin.class);
    PartyService party=mock(PartyService.class);
    ClanSettings clan=mock(ClanSettings.class);
    Player player=mock(Player.class);
    PartyLayoutSync adapter=new PartyLayoutSync(plugin,client,party);
    PartyMember host=member(1,"Doc Sultan"), follower=member(2,"Teammate");

    static PartyMember member(long id,String name)
    {
        PartyMember m=mock(PartyMember.class);
        when(m.getMemberId()).thenReturn(id); when(m.getDisplayName()).thenReturn(name); when(m.isLoggedIn()).thenReturn(true); return m;
    }
    @Before public void setup()
    {
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN); when(client.getLocalPlayer()).thenReturn(player);
        when(player.getName()).thenReturn("Teammate"); when(client.getItemCount()).thenReturn(40000);
        when(client.getClanSettings(ClanID.GROUP_IRONMAN)).thenReturn(clan); when(clan.getName()).thenReturn("Group");
        ClanMember a=mock(ClanMember.class),b=mock(ClanMember.class);
        when(a.getName()).thenReturn("Doc Sultan"); when(b.getName()).thenReturn("Teammate");
        when(clan.getMembers()).thenReturn(Arrays.asList(a,b));
        when(party.isInParty()).thenReturn(true); when(party.getPartyId()).thenReturn(55L);
        when(party.getLocalMember()).thenReturn(follower); when(party.getMembers()).thenReturn(Arrays.asList(host,follower));
        when(plugin.savedLayout()).thenReturn(new StorageLayout(Arrays.asList(100,200)));
    }
    GroupStorageLayoutSyncMessage handshake()
    {
        adapter.configure(true,"Doc Sultan"); adapter.tick();
        ArgumentCaptor<GroupStorageLayoutSyncMessage> sent=ArgumentCaptor.forClass(GroupStorageLayoutSyncMessage.class);
        verify(party).send(sent.capture());
        GroupStorageLayoutSyncMessage reply=new GroupStorageLayoutSyncMessage(); reply.kind="snapshot"; reply.group="group";
        reply.session="host-session"; reply.token=sent.getValue().token; reply.layout="GSL1:200,100"; reply.setMemberId(1);
        return reply;
    }
    @Test public void validGroupHandshakeAppliesHostLayout()
    {
        GroupStorageLayoutSyncMessage m=handshake(); adapter.receive(m,adapter.generation);
        assertTrue(adapter.canEdit()); assertFalse(adapter.canReplace()); verify(plugin).acceptSyncedLayout(any(StorageLayout.class));
    }
    @Test public void hostWithoutLayoutGetsSetupInstructionsAndRepliesToFollower()
    {
        when(player.getName()).thenReturn("Doc Sultan"); when(party.getLocalMember()).thenReturn(host);
        when(plugin.savedLayout()).thenReturn(null);
        adapter.configure(true,"Doc Sultan"); adapter.tick();
        verify(plugin).syncStatus(contains("no saved layout yet"),eq(true),eq("Doc Sultan"));
        GroupStorageLayoutSyncMessage request=new GroupStorageLayoutSyncMessage();
        request.kind="get"; request.group="group"; request.token="fresh"; request.setMemberId(2);
        adapter.receive(request,adapter.generation);
        ArgumentCaptor<GroupStorageLayoutSyncMessage> sent=ArgumentCaptor.forClass(GroupStorageLayoutSyncMessage.class);
        verify(party).send(sent.capture());
        assertEquals("no-layout",sent.getValue().kind); assertEquals("fresh",sent.getValue().token);
        assertEquals(2,sent.getValue().recipient); assertTrue(adapter.canReplace());
    }
    @Test public void followerExplainsMissingHostLayoutWithoutApplyingAnything()
    {
        GroupStorageLayoutSyncMessage m=handshake(); m.kind="no-layout"; m.layout=null;
        adapter.receive(m,adapter.generation);
        verify(plugin).syncStatus(contains("they have no saved layout"),eq(true),eq("Doc Sultan"));
        verify(plugin,never()).acceptSyncedLayout(any()); assertFalse(adapter.canEdit());
    }
    @Test public void outsiderInPartyPausesAllSharing()
    {
        PartyMember outsider=member(3,"Outsider");
        when(party.getMembers()).thenReturn(Arrays.asList(host,follower,outsider));
        adapter.configure(true,"Doc Sultan"); adapter.tick();
        verify(party,never()).send(any(GroupStorageLayoutSyncMessage.class)); assertFalse(adapter.canEdit());
    }
    @Test public void untrustedSenderCannotApplySnapshot()
    {
        GroupStorageLayoutSyncMessage m=handshake(); m.setMemberId(99); adapter.receive(m,adapter.generation);
        verify(plugin,never()).acceptSyncedLayout(any()); assertFalse(adapter.canEdit());
    }
    @Test public void queuedMessageFromPriorProfileIsRejected()
    {
        GroupStorageLayoutSyncMessage m=handshake(); long old=adapter.generation;
        adapter.configure(true,"Doc Sultan"); adapter.receive(m,old);
        verify(plugin,never()).acceptSyncedLayout(any());
    }
    @Test public void changingPartyRejectsOldMessage()
    {
        GroupStorageLayoutSyncMessage m=handshake(); long old=adapter.generation;
        when(party.getPartyId()).thenReturn(66L); adapter.receive(m,old);
        verify(plugin,never()).acceptSyncedLayout(any());
    }
    @Test public void hostLeavingDisablesSharedEditing()
    {
        GroupStorageLayoutSyncMessage m=handshake(); adapter.receive(m,adapter.generation); assertTrue(adapter.canEdit());
        when(party.getMembers()).thenReturn(Collections.singletonList(follower)); assertFalse(adapter.canEdit());
    }
    @Test public void invalidGameItemCannotReachRendering()
    {
        GroupStorageLayoutSyncMessage m=handshake(); m.layout="GSL1:999999"; adapter.receive(m,adapter.generation);
        verify(plugin,never()).acceptSyncedLayout(any()); assertFalse(adapter.canEdit());
    }
    @Test public void transportFailureDoesNotDiscardLocalLayoutOrThrow()
    {
        doThrow(new IllegalStateException("disconnected")).when(party).send(any(GroupStorageLayoutSyncMessage.class));
        adapter.configure(true,"Doc Sultan"); adapter.tick();
        assertFalse(adapter.canEdit()); verify(plugin).syncNotice(contains("connection unavailable"));
        verify(plugin,never()).acceptSyncedLayout(any());
    }
    @Test public void hostEditsOutsidePartyThenRejoinsWithLatestSavedLayout()
    {
        when(player.getName()).thenReturn("Doc Sultan"); when(party.getLocalMember()).thenReturn(host);
        when(party.isInParty()).thenReturn(false);
        java.util.concurrent.atomic.AtomicReference<StorageLayout> saved=new java.util.concurrent.atomic.AtomicReference<>(new StorageLayout(Arrays.asList(100,200)));
        when(plugin.savedLayout()).thenAnswer(call -> saved.get());
        doAnswer(call -> { saved.set(call.getArgument(0)); return null; }).when(plugin).acceptSyncedLayout(any());
        adapter.configure(true,"Doc Sultan"); adapter.tick();
        assertTrue(adapter.canEdit()); assertTrue(adapter.canReplace());
        assertTrue(adapter.move(0,5,100));
        adapter.observe(Arrays.asList(200,300));
        assertEquals("GSL1:-1,200,-1,-1,-1,100,300",saved.get().encode());
        verify(party,never()).send(any(GroupStorageLayoutSyncMessage.class));
        // A new adapter represents restart: only the persisted layout is retained.
        adapter=new PartyLayoutSync(plugin,client,party); adapter.configure(true,"Doc Sultan");
        when(party.isInParty()).thenReturn(true); adapter.tick();
        GroupStorageLayoutSyncMessage request=new GroupStorageLayoutSyncMessage();
        request.kind="get"; request.group="group"; request.token="fresh-join"; request.setMemberId(2);
        adapter.receive(request,adapter.generation);
        ArgumentCaptor<GroupStorageLayoutSyncMessage> sent=ArgumentCaptor.forClass(GroupStorageLayoutSyncMessage.class);
        verify(party).send(sent.capture());
        assertEquals(saved.get().encode(),sent.getValue().layout);
        assertEquals("fresh-join",sent.getValue().token);
        assertTrue(adapter.move(5,0,100)); // live changes still use the shared protocol
        verify(party,times(2)).send(any(GroupStorageLayoutSyncMessage.class));
    }
    @Test public void followerCannotEditOrReplaceOutsideParty()
    {
        when(party.isInParty()).thenReturn(false); adapter.configure(true,"Doc Sultan"); adapter.tick();
        assertFalse(adapter.canEdit()); assertFalse(adapter.canReplace()); assertFalse(adapter.move(0,1,100));
        adapter.observe(Arrays.asList(300));
        verify(plugin,never()).acceptSyncedLayout(any()); verify(party,never()).send(any(GroupStorageLayoutSyncMessage.class));
    }
    @Test public void hostCanEditAfterLeavingAndCannotEditAsDifferentCharacter()
    {
        when(player.getName()).thenReturn("Doc Sultan"); when(party.getLocalMember()).thenReturn(host);
        adapter.configure(true,"Doc Sultan"); adapter.tick();
        when(party.isInParty()).thenReturn(false);
        assertTrue(adapter.move(0,3,100)); verify(plugin).acceptSyncedLayout(any());
        when(player.getName()).thenReturn("Teammate");
        assertFalse(adapter.canReplace()); assertFalse(adapter.move(0,4,100));
        when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
        when(player.getName()).thenReturn("Doc Sultan"); assertFalse(adapter.canEdit());
        verify(party,never()).send(any(GroupStorageLayoutSyncMessage.class));
    }
}

package com.docsultan.groupstorage;

import com.google.gson.Gson;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.name.Names;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.PartyDataService;
import net.runelite.client.party.messages.PartyData;
import net.runelite.client.task.Scheduler;
import net.runelite.client.party.WSClient;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import static org.mockito.Mockito.*;

/** Opt-in real relay smoke test. Synthetic items only; no game login or real profiles. */
public final class PartyRelaySmoke
{
    private static final List<Node> nodes=new ArrayList<>();
    private static final Path output=Paths.get("build","relay-smoke");

    public static final class Node implements AutoCloseable
    {
        final PartyService party;
        final WSClient socket;
        final OkHttpClient http=new OkHttpClient.Builder().pingInterval(10,TimeUnit.SECONDS).build();
        final Queue<GroupStorageLayoutSyncMessage> inbox=new ConcurrentLinkedQueue<>();
        final Path file;
        final String name;
        final Client client=mock(Client.class);
        final GroupStoragePlugin plugin=mock(GroupStoragePlugin.class);
        final List<String> notices=new ArrayList<>();
        StorageLayout saved;
        LayoutSync state;
        PartyLayoutSync adapter;
        String adapterStatus="";
        long received;
        Node(String name,String passphrase,StorageLayout initial) throws Exception
        {
            this.name="gsl"+name; file=output.resolve(name+".txt"); saved=initial;
            Player player=mock(Player.class); when(player.getName()).thenReturn(this.name);
            when(client.getLocalPlayer()).thenReturn(player); when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
            when(client.getItemCount()).thenReturn(40000);
            ClanSettings clan=mock(ClanSettings.class); when(clan.getName()).thenReturn("synthetic-relay-test");
            List<ClanMember> roster=new ArrayList<>();
            for(String memberName:Arrays.asList("gslhost","gslsecond","gslthird"))
            { ClanMember member=mock(ClanMember.class); when(member.getName()).thenReturn(memberName); roster.add(member); }
            when(clan.getMembers()).thenReturn(roster); when(client.getClanSettings(ClanID.GROUP_IRONMAN)).thenReturn(clan);
            when(plugin.savedLayout()).thenAnswer(call -> saved);
            doAnswer(call -> { save(call.getArgument(0)); return null; }).when(plugin).acceptSyncedLayout(any());
            doAnswer(call -> { adapterStatus=call.getArgument(0); return null; }).when(plugin).syncStatus(anyString(),anyBoolean(),anyString());
            EventBus bus=new EventBus();
            Injector injector=Guice.createInjector(new AbstractModule() {
                @Override protected void configure()
                {
                    bind(Client.class).toInstance(client);
                    bind(ClientThread.class).toInstance(mock(ClientThread.class));
                    bind(Scheduler.class).toInstance(mock(Scheduler.class));
                    bind(ChatMessageManager.class).toInstance(mock(ChatMessageManager.class));
                    bind(EventBus.class).toInstance(bus);
                    bind(OkHttpClient.class).toInstance(http);
                    bind(Gson.class).toInstance(new Gson());
                    bind(HttpUrl.class).annotatedWith(Names.named("runelite.ws"))
                        .toInstance(HttpUrl.get("https://api.runelite.net/ws2"));
                }
            });
            party=injector.getInstance(PartyService.class); socket=injector.getInstance(WSClient.class);
            injector.getInstance(PartyDataService.class);
            socket.registerMessage(GroupStorageLayoutSyncMessage.class); bus.register(this);
            nodes.add(this); party.changeParty(passphrase);
        }
        void identify() { PartyData data=new PartyData(); data.setCharacterName(name); party.send(data); }
        void startAdapter()
        {
            state=null; inbox.clear(); adapter=new PartyLayoutSync(plugin,client,party); adapter.configure(true,"gslhost");
        }
        @Subscribe public void onGroupStorageLayoutSyncMessage(GroupStorageLayoutSyncMessage message) { inbox.add(message); }
        void start(boolean host,long leader)
        {
            inbox.clear();
            state=new LayoutSync(host,party.getLocalMember().getMemberId(),leader,"synthetic-relay-test",saved,
                party::send,this::save,notices::add,System::currentTimeMillis);
        }
        void save(StorageLayout layout)
        {
            saved=layout;
            try { Files.writeString(file,layout.encode()); }
            catch(Exception ex) { throw new IllegalStateException(ex); }
        }
        void pump()
        {
            GroupStorageLayoutSyncMessage message;
            while((message=inbox.poll())!=null)
            { received++; if(adapter!=null) adapter.receive(message,adapter.generation); else if(state!=null) state.receive(message); }
            if(adapter!=null) adapter.tick();
            if(state!=null) state.tick();
        }
        @Override public void close()
        {
            state=null; adapter=null; party.changeParty(null); socket.close();
            http.dispatcher().executorService().shutdownNow(); http.connectionPool().evictAll();
        }
    }
    private static void await(String label,BooleanSupplier done) throws Exception
    {
        long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(25);
        while(System.nanoTime()<until)
        {
            for(Node node:nodes) node.pump();
            if(done.getAsBoolean()) { System.out.println("PASS: "+label); return; }
            Thread.sleep(25);
        }
        throw new AssertionError("Timed out: "+label);
    }
    private static boolean same(Node... values)
    {
        for(Node n:values) if(!values[0].saved.encode().equals(n.saved.encode())) return false;
        return true;
    }
    public static void main(String[] args) throws Exception
    {
        Files.createDirectories(output);
        String passphrase="gsl-smoke-"+UUID.randomUUID(); // isolated disposable party; never a user's party
        try
        {
            Node host=new Node("host",passphrase,new StorageLayout(Arrays.asList(4151,11806,27277)));
            Node second=new Node("second",passphrase,new StorageLayout(Arrays.asList(100)));
            Node third=new Node("third",passphrase,new StorageLayout(Arrays.asList(200)));
            await("three independent Party connections joined",() -> nodes.stream().allMatch(n -> n.party.getLocalMember()!=null && n.party.getMembers().size()==3));
            long leader=host.party.getLocalMember().getMemberId();
            host.start(true,leader); second.start(false,leader); third.start(false,leader);
            await("initial shared layout delivered",() -> second.state.ready() && third.state.ready() && same(host,second,third));
            if(!host.state.move(2,10,27277)) throw new AssertionError("host drag rejected");
            await("host Shadow move broadcast to both followers",() -> same(host,second,third) && second.saved.itemAt(10)==27277);
            if(!second.state.move(10,12,27277)) throw new AssertionError("follower drag rejected");
            await("follower drag acknowledged and persisted on all three",() -> same(host,second,third) && !second.state.pending() && third.saved.itemAt(12)==27277);
            if(!second.state.move(0,6,4151) || !third.state.move(1,7,11806)) throw new AssertionError("concurrent drags not sent");
            await("concurrent edits converge with one conflict rejection",() -> same(host,second,third) && !second.state.pending() && !third.state.pending() && second.notices.size()+third.notices.size()==1);
            host.state=null; host.party.changeParty(null);
            // Relay rosters retain disconnected members temporarily. Liveness must use
            // our acknowledged snapshots, not immediate removal from the member list.
            await("host timeout pauses follower edits despite retained Party roster",() -> !second.state.ready() && !third.state.ready());
            if(second.state.move(12,15,27277)) throw new AssertionError("offline follower edit accepted");
            // Same persisted-layout path used by the offline host adapter; no network send.
            StorageLayout offline=StorageLayout.decode(Files.readString(host.file)); offline.swap(12,20); host.save(offline);
            host.party.changeParty(passphrase);
            await("host reconnect observed",() -> host.party.getLocalMember()!=null
                && second.party.getMemberById(host.party.getLocalMember().getMemberId())!=null
                && third.party.getMemberById(host.party.getLocalMember().getMemberId())!=null);
            leader=host.party.getLocalMember().getMemberId();
            host.saved=StorageLayout.decode(Files.readString(host.file));
            host.start(true,leader); second.start(false,leader); third.start(false,leader);
            await("offline host edit replaces older follower copies",() -> second.state.ready() && third.state.ready() && same(host,second,third) && third.saved.itemAt(20)==27277);
            for(Node node:nodes) if(!Files.readString(node.file).equals(host.saved.encode())) throw new AssertionError("persistence mismatch");
            // Exercise the production adapter with real Party name messages and a mocked
            // GIM roster. A fresh party avoids retained old connections from the prior test.
            String adapterParty="gsl-adapter-"+UUID.randomUUID();
            for(Node node:nodes) { node.state=null; node.party.changeParty(adapterParty); }
            await("adapter test party joined",() -> nodes.stream().allMatch(n -> n.party.getLocalMember()!=null && n.party.getMembers().size()==3));
            for(Node node:nodes) node.identify();
            await("real PartyDataService received all synthetic character names",() -> nodes.stream().allMatch(n -> n.party.getMembers().stream().allMatch(m -> m.isLoggedIn())));
            for(Node node:nodes) node.startAdapter();
            await("production adapters trust roster and sync",() -> second.adapter.canEdit() && third.adapter.canEdit() && same(host,second,third));
            if(!host.adapter.move(20,22,27277)) throw new AssertionError("adapter host drag rejected");
            await("adapter host move reaches both followers",() -> same(host,second,third) && third.saved.itemAt(22)==27277);
            if(!second.adapter.move(22,24,27277)) throw new AssertionError("adapter follower drag rejected");
            await("adapter follower move acknowledged",() -> second.adapter.canEdit() && same(host,second,third) && third.saved.itemAt(24)==27277);
            host.party.changeParty(null);
            if(!host.adapter.move(24,26,27277)) throw new AssertionError("adapter offline host edit rejected");
            String rejoinParty="gsl-rejoin-"+UUID.randomUUID();
            for(Node node:nodes) node.party.changeParty(rejoinParty);
            await("new shared party joined after offline edit",() -> nodes.stream().allMatch(n -> n.party.getLocalMember()!=null && n.party.getMembers().size()==3));
            for(Node node:nodes) node.identify();
            await("adapter offline host edit syncs without toggling settings",() -> second.adapter.canEdit() && third.adapter.canEdit() && same(host,second,third) && third.saved.itemAt(26)==27277);
            String report="Real RuneLite WSClient + PartyService: 3 independent connections.\n"
                +"Passed initial sync, host drag, follower drag, concurrent conflict, disconnect, offline edit and reconnect.\n"
                +"Relay retains disconnected roster entries; follower liveness timeout passed.\n"
                +"Production PartyLayoutSync adapter + real PartyDataService: host/follower edits and offline edit then new shared party passed.\n"
                +"Synthetic names, items and mocked GIM roster only. No game login, UI or item transactions exercised.\n";
            Files.writeString(output.resolve("result.txt"),report); System.out.println(report);
        }
        finally { for(Node node:nodes) node.close(); }
    }
}

package com.docsultan.groupstorage;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class StorageLayoutTest
{
    @Test public void withdrawalReturnAndShuffledServerOrderKeepPositions()
    {
        StorageLayout l=new StorageLayout(Arrays.asList(100,200,300));
        l.remember(Arrays.asList(300,100)); // 200 withdrawn; server compresses/reorders.
        assertEquals(200,l.itemAt(1));
        l.remember(Arrays.asList(200,300,100)); // Someone returns 200 at native index zero.
        assertEquals(Arrays.asList(100,200,300),l.items());
    }
    @Test public void draggingPlaceholderToGapSurvivesSaveAndReturn()
    {
        StorageLayout l=new StorageLayout(Arrays.asList(100,200,300));
        l.remember(Arrays.asList(100,300));
        l.swap(1,10);
        StorageLayout reloaded=StorageLayout.decode(l.encode());
        reloaded.remember(Arrays.asList(200,300,100));
        assertEquals(200,reloaded.itemAt(10)); assertEquals(-1,reloaded.itemAt(1));
    }
    @Test public void occupiedDragSwapsWithoutLosingEitherItem()
    {
        StorageLayout l=new StorageLayout(Arrays.asList(100,200,300)); l.swap(0,2);
        assertEquals(Arrays.asList(300,200,100),l.items());
    }
    @Test public void newItemsAppendWithoutFillingIntentionalGaps()
    {
        StorageLayout l=new StorageLayout(Arrays.asList(100,-1,300)); l.remember(Arrays.asList(100,400));
        assertEquals(Arrays.asList(100,-1,300,400),l.items());
    }
    @Test public void separateVariantsNeverShareAWithdrawalSlot()
    {
        StorageLayout l=new StorageLayout(); l.remember(Arrays.asList(2434,139,141,143));
        assertEquals(4,l.size());
    }
    @Test public void teamExportRoundTripPreservesAllPositions()
    {
        StorageLayout l=new StorageLayout(Arrays.asList(20997,-1,27275,11802));
        assertEquals(l.items(),StorageLayout.decode(l.encode()).items());
    }
    @Test public void invalidImportsAreRejected()
    {
        for(String text:Arrays.asList("", "GSL2:100", "GSL1:100,100", "GSL1:0", "GSL1:-2", "GSL1:100,", "GSL1:abc", "GSL1:1000001"))
        {
            try { StorageLayout.decode(text); fail("Accepted: "+text); }
            catch(IllegalArgumentException expected) { }
        }
    }
    @Test public void randomizedWithdrawalsDoNotEraseOrReassignItems()
    {
        StorageLayout l=new StorageLayout(); List<Integer> ids=new ArrayList<>();
        for(int i=1;i<=200;i++) ids.add(i);
        l.remember(ids); Random random=new Random(5234);
        for(int i=0;i<1000;i++)
        {
            List<Integer> before=l.items();
            Collections.shuffle(ids,random); l.remember(ids.subList(0,random.nextInt(ids.size())));
            assertEquals(before,l.items());
            l.swap(random.nextInt(200),random.nextInt(220));
            Set<Integer> actual=new HashSet<>(l.items()); actual.remove(-1);
            assertEquals(new HashSet<>(ids),actual);
        }
    }
    @Test public void capacityFailureDoesNotPartlyModifyLayout()
    {
        List<Integer> full=new ArrayList<>(); for(int i=1;i<=StorageLayout.MAX_SLOTS;i++) full.add(i);
        StorageLayout l=new StorageLayout(full);
        try { l.remember(Arrays.asList(9999)); fail(); } catch(IllegalArgumentException expected) { }
        assertEquals(full,l.items());
    }
}

package com.docsultan.groupstorage;

import java.awt.Rectangle;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.mockito.Mockito.*;

public class WidgetPlacementTest
{
    @Test public void movingAndRestoringNeverRewritesNativeActionIdentity()
    {
        Widget w=mock(Widget.class);
        when(w.getOriginalX()).thenReturn(8); when(w.getOriginalY()).thenReturn(36);
        when(w.getDragDeadTime()).thenReturn(5); when(w.isSelfHidden()).thenReturn(false);
        WidgetPlacement placement=new WidgetPlacement(w);
        placement.place(new Rectangle(104,108,36,32)); placement.restore();
        verify(w).setOriginalX(104); verify(w).setOriginalY(108);
        verify(w).setOriginalX(8); verify(w).setOriginalY(36);
        verify(w).setDragDeadTime(Integer.MAX_VALUE); verify(w).setDragDeadTime(5);
        verify(w,never()).setItemId(anyInt()); verify(w,never()).setItemQuantity(anyInt());
        verify(w,never()).clearActions(); verify(w,never()).setChildren(any());
        verify(w,never()).setOnOpListener(any(Object[].class));
    }
}
